* {
  box-sizing: border-box;
}

:root {
  --ink: #111318;
  --muted: #667085;
  --line: #dfe3e8;
  --surface: #ffffff;
  --canvas: #f3f5f7;
  --blue: #1d4ed8;
  --green: #15803d;
  --red: #c52233;
  --amber: #b45309;
  --cyan: #087e8b;
}

body {
  margin: 0;
  background: var(--canvas);
  color: var(--ink);
  font-family: Inter, Arial, sans-serif;
  letter-spacing: 0;
}

.dashboard {
  min-height: 100vh;
  padding: 20px;
}

/* Header */
.header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  margin-bottom: 14px;
  padding: 22px 24px;
  background: #17191f;
  color: #ffffff;
  border-left: 6px solid var(--blue);
}

.header span {
  color: #93b4ff;
  font-size: 10px;
  font-weight: 800;
  text-transform: uppercase;
}

.header h1 {
  margin: 5px 0;
  font-size: 28px;
  line-height: 1.1;
}

.header p {
  margin: 0;
  color: #aeb5c2;
  font-size: 11px;
}

.actions {
  display: flex;
  gap: 8px;
}

button {
  min-height: 38px;
  padding: 9px 18px;
  border: 1px solid var(--blue);
  border-radius: 5px;
  background: var(--blue);
  color: #ffffff;
  font-weight: 750;
  cursor: pointer;
  transition: transform 120ms ease, background 120ms ease;
}

button:hover {
  background: #173ea9;
  transform: translateY(-1px);
}

button.secondary {
  border-color: #4a505d;
  background: #292d36;
  color: #ffffff;
}

/* Filters */
.filters {
  display: grid;
  grid-template-columns: repeat(4, minmax(150px, 1fr));
  gap: 10px;
  margin-bottom: 14px;
  padding: 12px;
  background: var(--surface);
  border: 1px solid var(--line);
  border-left: 4px solid var(--cyan);
}

.filters label {
  color: var(--muted);
  font-size: 9px;
  font-weight: 800;
  text-transform: uppercase;
}

input,
select {
  width: 100%;
  height: 38px;
  margin-top: 5px;
  padding: 8px 10px;
  border: 1px solid #cfd5dd;
  border-radius: 4px;
  background: #ffffff;
  color: var(--ink);
  font-weight: 650;
  outline: none;
}

input:focus,
select:focus {
  border-color: var(--blue);
  box-shadow: 0 0 0 3px rgba(29, 78, 216, 0.12);
}

/* KPI Metrics */
.metrics {
  display: grid;
  grid-template-columns: repeat(4, minmax(150px, 1fr));
  gap: 10px;
  margin-bottom: 14px;
}

.metrics article {
  position: relative;
  min-height: 95px;
  padding: 15px;
  overflow: hidden;
  background: var(--surface);
  border: 1px solid var(--line);
  border-top: 4px solid var(--blue);
  box-shadow: 0 4px 12px rgba(17, 19, 24, 0.05);
}

.metrics article:nth-child(2) {
  border-top-color: var(--cyan);
}

.metrics article:nth-child(3) {
  border-top-color: var(--green);
}

.metrics article:nth-child(4) {
  border-top-color: #7c3aed;
}

.metrics article:nth-child(7) {
  border-top-color: #db2777;
}

.metrics article:nth-child(8) {
  border-top-color: #475569;
}

.metrics article::after {
  position: absolute;
  right: -15px;
  bottom: -28px;
  width: 75px;
  height: 75px;
  border: 12px solid #eef2f7;
  border-radius: 50%;
  content: "";
}

.metrics span {
  position: relative;
  z-index: 1;
  display: block;
  color: var(--muted);
  font-size: 9px;
  font-weight: 800;
  text-transform: uppercase;
}

.metrics strong {
  position: relative;
  z-index: 1;
  display: block;
  margin-top: 12px;
  font-size: 24px;
  line-height: 1;
}

.metrics .danger {
  border-top-color: var(--red);
  background: #fffafb;
}

.metrics .danger strong {
  color: var(--red);
}

.metrics .warning {
  border-top-color: var(--amber);
  background: #fffdf8;
}

.metrics .warning strong {
  color: var(--amber);
}

/* Panels */
.layout {
  display: grid;
  grid-template-columns: minmax(0, 1.35fr) minmax(320px, 0.65fr);
  gap: 12px;
  margin-bottom: 12px;
}

.layout:nth-of-type(n + 4) {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.panel {
  min-width: 0;
  padding: 15px;
  background: var(--surface);
  border: 1px solid var(--line);
  box-shadow: 0 5px 15px rgba(17, 19, 24, 0.045);
}

.panel h2 {
  display: flex;
  align-items: center;
  gap: 8px;
  margin: 0 0 14px;
  padding-bottom: 10px;
  border-bottom: 1px solid var(--line);
  font-size: 13px;
}

.panel h2::before {
  width: 4px;
  height: 17px;
  background: var(--blue);
  content: "";
}

/* Chart */
.chart {
  width: 100%;
  height: 245px;
  overflow: visible;
  background: linear-gradient(#edf0f4 1px, transparent 1px);
  background-size: 100% 25%;
}

.chart-line {
  fill: none;
  stroke: var(--blue);
  stroke-width: 3;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.chart circle {
  fill: #ffffff;
  stroke: var(--red);
  stroke-width: 3;
  cursor: pointer;
  transition: r 120ms ease;
}

.chart circle:hover {
  r: 7;
}

/* Alerts */
.alerts {
  display: grid;
  gap: 8px;
}

.alert {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  min-height: 55px;
  padding: 10px 12px;
  background: #f7f8fa;
  border: 1px solid #e5e8ed;
  border-left: 5px solid var(--blue);
}

.alert.high {
  background: #fff8f8;
  border-left-color: var(--red);
}

.alert.medium {
  background: #fffbf3;
  border-left-color: var(--amber);
}

.alert div {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 4px;
}

.alert strong {
  font-size: 10px;
}

.alert span {
  color: var(--muted);
  font-size: 8px;
  line-height: 1.4;
}

.alert b {
  min-width: 35px;
  font-size: 20px;
  text-align: right;
}

/* Tables */
.table-wrap {
  max-height: 330px;
  overflow: auto;
  border: 1px solid var(--line);
}

table {
  width: 100%;
  border-collapse: collapse;
  font-size: 9px;
}

thead {
  position: sticky;
  z-index: 2;
  top: 0;
}

th,
td {
  padding: 8px;
  border-bottom: 1px solid #e7e9ee;
  text-align: left;
  white-space: nowrap;
}

th {
  background: #f0f2f5;
  color: #4b5563;
  font-size: 8px;
  font-weight: 850;
  text-transform: uppercase;
}

tbody tr:nth-child(even) {
  background: #fafbfc;
}

tbody tr:hover {
  background: #eef4ff;
}

td:nth-last-child(-n+2) {
  font-weight: 700;
}

/* Empty States */
.empty {
  display: grid;
  min-height: 130px;
  place-items: center;
  padding: 25px 10px;
  color: var(--muted);
  font-size: 10px;
  text-align: center;
  border: 1px dashed #ccd2da;
  background: #fafbfc;
}

/* Responsive */
@media (max-width: 1050px) {
  .metrics {
    grid-template-columns: repeat(2, 1fr);
  }
  .layout,
  .layout:nth-of-type(n + 4) {
    grid-template-columns: 1fr;
  }
}
@media (max-width: 720px) {
  .dashboard {
    padding: 10px;
  }
  .header {
    align-items: flex-start;
    flex-direction: column;
  }
  .filters,
  .metrics {
    grid-template-columns: 1fr;
  }
  .actions {
    width: 100%;
  }
  .actions button {
    flex: 1;
  }
}
/* Print */
@page {
  size: A4 landscape;
  margin: 8mm;
}
@media print {
  body,
  .dashboard {
    padding: 0;
    background: #ffffff;
  }
  .no-print {
    display: none !important;
  }
  .header {
    padding: 12px;
    background: #ffffff;
    color: #111318;
    border: 1px solid #111318;
  }
  .header p {
    color: #4b5563;
  }
  .metrics {
    grid-template-columns: repeat(4, 1fr);
  }
  .layout,
  .layout:nth-of-type(n + 4) {
    grid-template-columns: 1fr 1fr;
  }
  .panel,
  .metrics article {
    break-inside: avoid;
    box-shadow: none;
  }
  .table-wrap {
    max-height: none;
    overflow: visible;
  }
}

