function money(value) {
  return new Intl.NumberFormat("hr-HR", {
    style: "currency",
    currency: "EUR"
  }).format(Number(value || 0));
}
function number(value) {
  return new Intl.NumberFormat("hr-HR", {
    maximumFractionDigits: 2
  }).format(Number(value || 0));
}
function escapeHtml(value) {
  return String(value ?? "").replaceAll("&", "&amp;").replaceAll("<", "&lt;").replaceAll(">", "&gt;");
}
function trendChart(rows) {
  if (!rows.length) return `<div class="empty">No sales in selected period.</div>`;
  const width = 900;
  const height = 230;
  const padding = 25;
  const max = Math.max(...rows.map(row => Number(row.salesAmount || 0)), 1);
  const points = rows.map((row, index) => {
    const x = padding + index * ((width - padding * 2) / Math.max(rows.length - 1, 1));
    const y = height - padding - Number(row.salesAmount || 0) / max * (height - padding * 2);
    return `${x},${y}`;
  }).join(" ");
  return `
    <svg viewBox="0 0 ${width} ${height}" class="chart">
      <polyline class="chart-line" points="${points}" />
      ${rows.map((row, index) => {
    const [x, y] = points.split(" ")[index].split(",");
    return `<circle cx="${x}" cy="${y}" r="4">
          <title>${escapeHtml(row.saleDate)}: ${money(row.salesAmount)}</title>
        </circle>`;
  }).join("")}
    </svg>
  `;
}
async function refreshDashboard() {
  const filters = {
    dateFrom: document.getElementById("dateFrom").value,
    dateTo: document.getElementById("dateTo").value,
    warehouseId: Number(document.getElementById("warehouse").value || 0),
    categoryId: Number(document.getElementById("category").value || 0)
  };
  await appsmith.updateModel({
    ...appsmith.model,
    filters
  });
  appsmith.triggerEvent("onRefresh");
}
function render() {
  const model = appsmith.model || {};
  const overview = model.overview || {};
  const filters = model.filters || {};
  const alerts = model.alerts || [];
  const topProducts = model.topProducts || [];
  const slowProducts = model.slowProducts || [];
  const warehouseStock = model.warehouseStock || [];
  const priceChanges = model.priceChanges || [];
  document.getElementById("root").innerHTML = `
    <div class="dashboard">
      <header class="header">
        <div>
          <span>PRODUCT INTELLIGENCE</span>
          <h1>Product Dashboard</h1>
          <p>Refreshed: ${escapeHtml(model.refreshedAt || "-")}</p>
        </div>

        <div class="actions no-print">
          <button id="refreshButton">Refresh</button>
          <button class="secondary" onclick="window.print()">Print</button>
        </div>
      </header>

      <section class="filters no-print">
        <label>From<input id="dateFrom" type="date" value="${filters.dateFrom || ""}"></label>
        <label>To<input id="dateTo" type="date" value="${filters.dateTo || ""}"></label>

        <label>Warehouse
          <select id="warehouse">
            ${(model.warehouses || []).map(row => `<option value="${row.value}" ${Number(row.value) === Number(filters.warehouseId) ? "selected" : ""}>
                ${escapeHtml(row.label)}
              </option>`).join("")}
          </select>
        </label>

        <label>Category
          <select id="category">
            ${(model.categories || []).map(row => `<option value="${row.value}" ${Number(row.value) === Number(filters.categoryId) ? "selected" : ""}>
                ${escapeHtml(row.label)}
              </option>`).join("")}
          </select>
        </label>
      </section>

      <section class="metrics">
        <article><span>Active Products</span><strong>${number(overview.activeProducts)}</strong></article>
        <article><span>Stock Quantity</span><strong>${number(overview.totalStockQuantity)}</strong></article>
        <article><span>Stock Value</span><strong>${money(overview.totalStockValue)}</strong></article>
        <article><span>Average Margin</span><strong>${number(overview.averageMarginPercent)}%</strong></article>
        <article class="danger"><span>Out of Stock</span><strong>${number(overview.outOfStockProducts)}</strong></article>
        <article class="warning"><span>Low Stock</span><strong>${number(overview.lowStockProducts)}</strong></article>
        <article><span>Active Promotions</span><strong>${number(overview.activePromotions)}</strong></article>
        <article><span>Pending Price Changes</span><strong>${number(overview.pendingPriceChanges)}</strong></article>
      </section>

      <section class="layout">
        <article class="panel large">
          <h2>Sales Trend</h2>
          ${trendChart(model.salesTrend || [])}
        </article>

        <article class="panel">
          <h2>Requires Attention</h2>
          <div class="alerts">
            ${alerts.length ? alerts.map(row => `
              <div class="alert ${String(row.severity).toLowerCase()}">
                <div><strong>${escapeHtml(row.title)}</strong><span>${escapeHtml(row.actionText)}</span></div>
                <b>${number(row.countValue)}</b>
              </div>
            `).join("") : `<div class="empty">No active alerts.</div>`}
          </div>
        </article>
      </section>

      <section class="layout">
        <article class="panel">
          <h2>Top Products</h2>
          ${table(topProducts, [["productCode", "Code"], ["productName", "Product"], ["soldQuantity", "Qty"], ["salesAmount", "Sales", money]])}
        </article>

        <article class="panel">
          <h2>Slow Moving Stock</h2>
          ${table(slowProducts, [["productCode", "Code"], ["productName", "Product"], ["stockQuantity", "Stock"], ["lastSaleDate", "Last Sale"]])}
        </article>
      </section>

      <section class="layout">
        <article class="panel">
          <h2>Warehouse Stock</h2>
          ${table(warehouseStock, [["warehouseCode", "Code"], ["warehouseName", "Warehouse"], ["productCount", "Products"], ["stockQuantity", "Quantity"], ["stockValue", "Value", money]])}
        </article>

        <article class="panel">
          <h2>Recent Price Changes</h2>
          ${table(priceChanges, [["recordNumber", "Record"], ["effectiveDate", "Effective"], ["changeType", "Type"], ["status", "Status"], ["itemCount", "Items"]])}
        </article>
      </section>
    </div>
  `;
  document.getElementById("refreshButton").onclick = refreshDashboard;
}
function table(rows, columns) {
  if (!rows.length) return `<div class="empty">No data available.</div>`;
  return `
    <div class="table-wrap">
      <table>
        <thead><tr>${columns.map(column => `<th>${column[1]}</th>`).join("")}</tr></thead>
        <tbody>
          ${rows.map(row => `
            <tr>
              ${columns.map(column => `
                <td>${column[2] ? column[2](row[column[0]]) : escapeHtml(row[column[0]] ?? "-")}</td>
              `).join("")}
            </tr>
          `).join("")}
        </tbody>
      </table>
    </div>
  `;
}
appsmith.onReady(() => {
  render();
  appsmith.onModelChange(render);
});

