  border-left: 5px solid var(--blue);
}

.alert.high {
  background: #fff8f8;
  border-left-color: var(--red);
}

.alert.medium {
  background: #fffbf3;
  border-left-color: var(--amber);
}

.alert div {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 4px;
}

.alert strong {
  font-size: 10px;
}

.alert span {
  color: var(--muted);
  font-size: 8px;
  line-height: 1.4;
}

.alert b {
  min-width: 35px;
  font-size: 20px;
  text-align: right;
}

/* Tables */

.table-wrap {
  max-height: 330px;
  overflow: auto;
  border: 1px solid var(--line);
}

table {
  width: 100%;
  border-collapse: collapse;
  font-size: 9px;
}

thead {
  position: sticky;
  z-index: 2;
  top: 0;
}

th,
td {
  padding: 8px;
  border-bottom: 1px solid #e7e9ee;
  text-align: left;
  white-space: nowrap;
}

th {
  background: #f0f2f5;
  color: #4b5563;
  font-size: 8px;
  font-weight: 850;
  text-transform: uppercase;
}

tbody tr:nth-child(even) {
  background: #fafbfc;
}

tbody tr:hover {
  background: #eef4ff;
}

td:nth-last-child(-n + 2) {
  font-weight: 700;
}

/* Empty States */

.empty {
  display: grid;
  min-height: 130px;
  place-items: center;
  padding: 25px 10px;
  color: var(--muted);
  font-size: 10px;
  text-align: center;
  border: 1px dashed #ccd2da;
  background: #fafbfc;
}

/* Responsive */

@media (max-width: 1050px) {
  .metrics {
    grid-template-columns: repeat(2, 1fr);
  }

  .layout,
  .layout:nth-of-type(n + 4) {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 720px) {
  .dashboard {
    padding: 10px;
  }

  .header {
    align-items: flex-start;
    flex-direction: column;
  }

  .filters,
  .metrics {
    grid-template-columns: 1fr;
  }

  .actions {
    width: 100%;
  }

  .actions button {
    flex: 1;
  }
}

/* Print */

@page {
  size: A4 landscape;
  margin: 8mm;
}

@media print {
  body,
  .dashboard {
    padding: 0;
    background: #ffffff;
  }

  .no-print {
    display: none !important;
  }

  .header {
    padding: 12px;
    background: #ffffff;
    color: #111318;
    border: 1px solid #111318;
  }

  .header p {
    color: #4b5563;
  }

  .metrics {
    grid-template-columns: repeat(4, 1fr);
  }

  .layout,
  .layout:nth-of-type(n + 4) {
    grid-template-columns: 1fr 1fr;
  }

  .panel,
  .metrics article {
    break-inside: avoid;
    box-shadow: none;
  }

  .table-wrap {
    max-height: none;
    overflow: visible;
  }
}

